def sum_of_primes(limit):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    return sum(i for i in range(2, limit+1) if is_prime(i))
sum_of_primes(500)

